    /** Lowercase hex SHA-256 of canonical bytes (checked first). */
    hash: (bytes) => str(call("bxm_hash", [toBytes(bytes, "bytes")])),
    /** Lowercase hex SHA-256 of the canonical encoding of a text value. */
